import { useState } from "react";

const tabs = ["Overview", "Nordstrom Rack", "Saachistyle", "Rue La La", "B2B: Faire", "B2B: FashionGo", "Wolf & Badger", "Inventory Alerts"];

// Color system
const C = {
  bg: "#08070a", card: "#111015", border: "#1e1c24", borderHi: "#2d2a36",
  text: "#d4d0de", textMute: "#706b80", textDim: "#4a4558",
  gold: "#d4a857", goldDim: "#8a7340",
  green: "#3dd68c", greenDim: "#1a4d38",
  red: "#f06070", redDim: "#4d1a22",
  blue: "#5c9cf5", blueDim: "#1a2d4d",
  purple: "#b47aeb", purpleDim: "#2d1a4d",
  orange: "#e8924a", orangeDim: "#4d2d1a",
  cyan: "#4ad8d0", cyanDim: "#1a4d4a",
};

const font = "'DM Sans', system-ui, sans-serif";
const fontDisplay = "'Playfair Display', Georgia, serif";

function KPI({ label, value, sub, color }) {
  return (
    <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 10, padding: "0.85rem 1rem" }}>
      <div style={{ fontFamily: font, fontSize: "0.58rem", color: C.textMute, letterSpacing: "0.08em", textTransform: "uppercase" }}>{label}</div>
      <div style={{ fontFamily: fontDisplay, fontSize: "1.4rem", fontWeight: 400, color: color || C.text, margin: "0.15rem 0" }}>{value}</div>
      {sub && <div style={{ fontFamily: font, fontSize: "0.62rem", color: C.textDim }}>{sub}</div>}
    </div>
  );
}

function SectionTitle({ children, color }) {
  return (
    <div style={{ fontFamily: font, fontSize: "0.6rem", letterSpacing: "0.18em", textTransform: "uppercase", color: color || C.textMute, fontWeight: 600, marginBottom: "0.6rem", marginTop: "1.25rem" }}>
      {children}
    </div>
  );
}

function Alert({ type, title, children }) {
  const colors = type === "danger" ? { bg: "#2a0a0e", border: "#5c1a22", accent: C.red }
    : type === "warning" ? { bg: "#2a1f0a", border: "#5c4a1a", accent: C.orange }
    : { bg: "#0a2a1a", border: "#1a5c3a", accent: C.green };
  return (
    <div style={{ background: colors.bg, border: `1px solid ${colors.border}`, borderRadius: 10, padding: "0.9rem 1.1rem", marginBottom: "0.6rem" }}>
      <div style={{ fontFamily: font, fontSize: "0.62rem", fontWeight: 600, color: colors.accent, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: "0.35rem" }}>{title}</div>
      <div style={{ fontFamily: font, fontSize: "0.75rem", color: C.text, lineHeight: 1.6 }}>{children}</div>
    </div>
  );
}

function ProductRow({ sku, name, rev, qty, ats, wip, note, color, danger }) {
  const atsNum = typeof ats === 'number' ? ats : null;
  const atsColor = atsNum !== null ? (atsNum <= 0 ? C.red : atsNum <= 10 ? C.orange : atsNum <= 30 ? C.gold : C.green) : C.textDim;
  return (
    <div style={{ display: "grid", gridTemplateColumns: "minmax(180px, 2fr) 80px 55px 55px 55px 1fr", gap: "0.4rem", alignItems: "center", padding: "0.5rem 0.7rem", borderBottom: `1px solid ${C.border}`, fontSize: "0.72rem", fontFamily: font }}>
      <div>
        <span style={{ color: color || C.text }}>{name}</span>
        <span style={{ color: C.textDim, marginLeft: "0.4rem", fontSize: "0.6rem" }}>{sku}</span>
      </div>
      <div style={{ color: C.gold, textAlign: "right" }}>${typeof rev === 'number' ? rev.toLocaleString() : rev}</div>
      <div style={{ color: C.textMute, textAlign: "right" }}>{qty}</div>
      <div style={{ color: atsColor, textAlign: "right", fontWeight: atsNum !== null && atsNum <= 5 ? 700 : 400 }}>{ats}</div>
      <div style={{ color: C.textMute, textAlign: "right" }}>{wip}</div>
      <div style={{ fontSize: "0.65rem", color: danger ? C.red : C.textDim }}>{note}</div>
    </div>
  );
}

function TableHeader() {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "minmax(180px, 2fr) 80px 55px 55px 55px 1fr", gap: "0.4rem", padding: "0.4rem 0.7rem", borderBottom: `1px solid ${C.borderHi}`, fontSize: "0.58rem", fontFamily: font, color: C.textDim, textTransform: "uppercase", letterSpacing: "0.06em" }}>
      <div>Product</div>
      <div style={{ textAlign: "right" }}>Revenue</div>
      <div style={{ textAlign: "right" }}>Qty</div>
      <div style={{ textAlign: "right" }}>ATS</div>
      <div style={{ textAlign: "right" }}>WIP</div>
      <div>Action</div>
    </div>
  );
}

function CatBar({ cat, amt, pct, color }) {
  return (
    <div style={{ marginBottom: "0.4rem" }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontFamily: font, fontSize: "0.7rem", marginBottom: "0.15rem" }}>
        <span style={{ color: C.text }}>{cat}</span>
        <span style={{ color: color }}>${(amt/1000).toFixed(1)}K <span style={{ color: C.textDim }}>({pct}%)</span></span>
      </div>
      <div style={{ height: 5, background: C.border, borderRadius: 3 }}>
        <div style={{ height: "100%", width: `${Math.max(pct, 1)}%`, background: color, borderRadius: 3 }} />
      </div>
    </div>
  );
}

